const express = require('express');
const { expressjwt: jwt } = require('express-jwt');
const db = require('../db');

const app = express();

// Enforce asymmetric signature strictly per tenant without shared symmetric secret
const authenticateDev = jwt({
  secret: (req, token) => req.app.get('tenantPublicKey'),
  algorithms: ['RS256']
});

app.get('/api/dev/apps/:appId/credentials', authenticateDev, async (req, res) => {
  const { appId } = req.params;

  // Verify that the requested application is owned by the authenticated developer
  const appRecord = await db('developer_apps')
    .where({ id: appId, developer_id: req.auth.sub })
    .first();
  if (!appRecord) {
    return res.status(404).json({ error: 'Application not found' });
  }

  return res.json({
    appId: appRecord.id,
    clientId: appRecord.client_id,
    clientSecret: appRecord.client_secret,
    webhookSigningKey: appRecord.webhook_signing_key
  });
});

module.exports = app;
